window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-ccd6f7b33657aa10"]={"versions": [{"id": "FIG-ccd6f7b33657aa10", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm / Strukturschaubild zur Diagnosearchitektur der AUTOSAR Adaptive Platform. Das Diagramm illustriert das architektonische Konzept einer geteilten logischen Diagnoseadresse (<code>Shared diagnostic address 0x1234</code>) über mehrere Software Cluster hinweg innerhalb einer Machine.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das System umfasst folgende Software-Cluster-Instanzen (Typ <code>Software Cluster</code>):</p>\n<ul class=\"fig-list\"><li><code>Platform Core: Software Cluster</code>: Instanz der Kategorie <code>PLATFORM_CORE</code> mit der Eigenschaft <code>diagnosticAddress = 0x1234</code>.\n</li><li><code>Platform: Software Cluster</code>: Instanz der Kategorie <code>PLATFORM</code>.\n</li><li><code>app1: Software Cluster</code>: Anwendungs-Cluster der Kategorie <code>APPLICATION_LAYER</code>.\n</li><li><code>app2Root: Software Cluster</code>: Wurzel-Anwendungscluster der Kategorie <code>APPLICATION_LAYER</code>.\n</li><li><code>app2Sub1: Software Cluster</code> und <code>app2Sub2: Software Cluster</code>: Untergeordnete Anwendungscluster der Kategorie <code>APPLICATION_LAYER</code>, die über gestrichelte Pfeile von <code>app2Root</code> abhängen bzw. referenziert werden.\n</li></ul>\n<p class=\"fig-p\">Zentrales Diagnoseelement:</p>\n<ul class=\"fig-list\"><li><code>shared: DiagnosticContributionSet</code>: Geteilte Diagnosekonfiguration, enthaltend die Data Identifier <code>DID 0x2314</code> und <code>DID 0x4321</code>.\n</li></ul>\n<p class=\"fig-p\">Beziehungen / Schnittstellen:</p>\n<ul class=\"fig-list\"><li>Alle vier Cluster bzw. Root-Cluster (<code>app1</code>, <code>app2Root</code>, <code>Platform Core</code>, <code>Platform</code>) besitzen gerichtete Referenzpfeile mit offenen Pfeilspitzen auf <code>shared: DiagnosticContributionSet</code>.\n</li><li>Die gesamte Anordnung befindet sich innerhalb einer rot umrandeten logischen Hülle mit dem Titel <code>Shared diagnostic address 0x1234</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Deklarationsstruktur ohne zeitliche Sequenzabläufe oder Interaktionspfade. Das Diagramm modelliert die Zuordnung von Diagnoseelementen: Ein zentraler Root-Cluster (<code>Platform Core</code>) definiert die Diagnoseadresse für das Gesamtsystem, während alle beteiligten Software-Cluster über ihre Referenzen auf das gemeinsame <code>DiagnosticContributionSet</code> ihre jeweiligen Diagnosebestandteile (DIDs) beisteuern. Dadurch wird der Diagnoseserver für die gemeinsame Diagnoseadresse automatisiert über Clustergrenzen hinweg aggregiert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Exemplarisches Entwurfsmuster für AUTOSAR Adaptive Plattformarchitekturen:</p>\n<ul class=\"fig-list\"><li>Pro Diagnoseadresse darf jede DID systemweit in den zugeordneten <code>DiagnosticContributionSets</code> nur genau einmal vorkommen.\n</li><li>Nur ein einzelner Root-Software-Cluster definiert die Diagnoseadresse (<code>diagnosticAddress</code>), während andere Cluster über das gemeinsame <code>DiagnosticContributionSet</code> angebunden werden und den Diagnoseserver erweitern.\n</li><li>Die begleitenden Notizen weisen explizit darauf hin, dass Vereinfachungen und Auslassungen vorgenommen wurden, um das Prinzip der Adressenteilung übersichtlich darzustellen.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-fab7160ee7ceacae", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm / Strukturschaubild zur Diagnosearchitektur der AUTOSAR Adaptive Platform. Das Diagramm illustriert das architektonische Konzept einer geteilten logischen Diagnoseadresse (<code>Shared diagnostic address 0x1234</code>) über mehrere Software Cluster hinweg innerhalb einer Machine.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das System umfasst folgende Software-Cluster-Instanzen (Typ <code>Software Cluster</code>):</p>\n<ul class=\"fig-list\"><li><code>Platform Core: Software Cluster</code>: Instanz der Kategorie <code>PLATFORM_CORE</code> mit der Eigenschaft <code>diagnosticAddress = 0x1234</code>.\n</li><li><code>Platform: Software Cluster</code>: Instanz der Kategorie <code>PLATFORM</code>.\n</li><li><code>app1: Software Cluster</code>: Anwendungs-Cluster der Kategorie <code>APPLICATION_LAYER</code>.\n</li><li><code>app2Root: Software Cluster</code>: Wurzel-Anwendungscluster der Kategorie <code>APPLICATION_LAYER</code>.\n</li><li><code>app2Sub1: Software Cluster</code> und <code>app2Sub2: Software Cluster</code>: Untergeordnete Anwendungscluster der Kategorie <code>APPLICATION_LAYER</code>, die über gestrichelte Pfeile von <code>app2Root</code> abhängen bzw. referenziert werden.\n</li></ul>\n<p class=\"fig-p\">Zentrales Diagnoseelement:</p>\n<ul class=\"fig-list\"><li><code>shared: DiagnosticContributionSet</code>: Geteilte Diagnosekonfiguration, enthaltend die Data Identifier <code>DID 0x2314</code> und <code>DID 0x4321</code>.\n</li></ul>\n<p class=\"fig-p\">Beziehungen / Schnittstellen:</p>\n<ul class=\"fig-list\"><li>Alle vier Cluster bzw. Root-Cluster (<code>app1</code>, <code>app2Root</code>, <code>Platform Core</code>, <code>Platform</code>) besitzen gerichtete Referenzpfeile mit offenen Pfeilspitzen auf <code>shared: DiagnosticContributionSet</code>.\n</li><li>Die gesamte Anordnung befindet sich innerhalb einer rot umrandeten logischen Hülle mit dem Titel <code>Shared diagnostic address 0x1234</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Deklarationsstruktur ohne zeitliche Sequenzabläufe oder Interaktionspfade. Das Diagramm modelliert die Zuordnung von Diagnoseelementen: Ein zentraler Root-Cluster (<code>Platform Core</code>) definiert die Diagnoseadresse für das Gesamtsystem, während alle beteiligten Software-Cluster über ihre Referenzen auf das gemeinsame <code>DiagnosticContributionSet</code> ihre jeweiligen Diagnosebestandteile (DIDs) beisteuern. Dadurch wird der Diagnoseserver für die gemeinsame Diagnoseadresse automatisiert über Clustergrenzen hinweg aggregiert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Exemplarisches Entwurfsmuster für AUTOSAR Adaptive Plattformarchitekturen:</p>\n<ul class=\"fig-list\"><li>Pro Diagnoseadresse darf jede DID systemweit in den zugeordneten <code>DiagnosticContributionSets</code> nur genau einmal vorkommen.\n</li><li>Nur ein einzelner Root-Software-Cluster definiert die Diagnoseadresse (<code>diagnosticAddress</code>), während andere Cluster über das gemeinsame <code>DiagnosticContributionSet</code> angebunden werden und den Diagnoseserver erweitern.\n</li><li>Die begleitenden Notizen weisen explizit darauf hin, dass Vereinfachungen und Auslassungen vorgenommen wurden, um das Prinzip der Adressenteilung übersichtlich darzustellen.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-960e9d49d23d65ec", "releases": ["R23-11", "R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm / Strukturschaubild zur Diagnosearchitektur der AUTOSAR Adaptive Platform. Das Diagramm illustriert das architektonische Konzept einer geteilten logischen Diagnoseadresse (<code>Shared diagnostic address 0x1234</code>) über mehrere Software Cluster hinweg innerhalb einer Machine.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das System umfasst folgende Software-Cluster-Instanzen (Typ <code>Software Cluster</code>):</p>\n<ul class=\"fig-list\"><li><code>Platform Core: Software Cluster</code>: Instanz der Kategorie <code>PLATFORM_CORE</code>.\n</li><li><code>Platform: Software Cluster</code>: Instanz der Kategorie <code>PLATFORM</code>.\n</li><li><code>app1: Software Cluster</code>: Anwendungs-Cluster der Kategorie <code>APPLICATION_LAYER</code>.\n</li><li><code>app2: Software Cluster</code>: Anwendungs-Cluster der Kategorie <code>APPLICATION_LAYER</code>.\n</li></ul>\n<p class=\"fig-p\">Zentrales Diagnoseelement:</p>\n<ul class=\"fig-list\"><li><code>shared: DiagnosticContributionSet</code>: Geteilte Diagnosekonfiguration mit definierter Adresse und DIDs:\n<ul class=\"fig-list\"><li><code>diagnosticAddress = 0x1234</code>\n</li><li><code>DID 0x2314</code>\n</li><li><code>DID 0x4321</code>\n</li></ul>\n</li></ul>\n<p class=\"fig-p\">Beziehungen / Schnittstellen:</p>\n<ul class=\"fig-list\"><li>Alle vier Software-Cluster (<code>app1</code>, <code>app2</code>, <code>Platform Core</code>, <code>Platform</code>) referenzieren über gerichtete Pfeile mit offener Pfeilspitze direkt auf <code>shared: DiagnosticContributionSet</code>.\n</li><li>Die Komponenten sind in einem rot umrandeten Rahmen mit der Kopfzeile <code>Shared diagnostic address 0x1234</code> zusammengefasst.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Konfigurations- und Deklarationsstruktur ohne dynamische Ablaufsequenz. Die Diagnoseadresse wird auf Ebene des <code>DiagnosticContributionSet</code> festgelegt. Die einzelnen Software-Cluster (<code>Platform Core</code>, <code>Platform</code>, <code>app1</code>, <code>app2</code>) referenzieren dieses gemeinsame Set, wodurch der Diagnoseserver für die konfigurierte Diagnoseadresse über alle teilnehmenden Cluster hinweg modular aggregiert und erweitert wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Entwurfs- und Modellierungsrichtlinien für AUTOSAR Adaptive:</p>\n<ul class=\"fig-list\"><li>Die Diagnoseadresse (<code>diagnosticAddress</code>) wird direkt am <code>DiagnosticContributionSet</code> modelliert und nicht an einem einzelnen Software-Cluster.\n</li><li>Nur das <code>DiagnosticContributionSet</code> legt die Diagnoseadresse fest; alle beteiligten Software-Cluster erweitern den Diagnoseserver durch Referenzierung dieses Sets.\n</li><li>Jede DID darf innerhalb aller <code>DiagnosticContributionSets</code> für dieselbe Diagnoseadresse nur genau einmal vergeben werden.\n</li><li>Begleitender Hinweis: Vereinfachungen und Auslassungen an der Diagnosekonfiguration dienen der didaktischen Veranschaulichung.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-ccd6f7b33657aa10", "to": "FIG-fab7160ee7ceacae", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-fab7160ee7ceacae", "to": "FIG-960e9d49d23d65ec", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>Platform Core: Software Cluster</code>: Attribut <code>diagnosticAddress = 0x1234</code> entfällt.\n</li><li><code>shared: DiagnosticContributionSet</code>: Attribut <code>diagnosticAddress = 0x1234</code> ergänzt.\n</li><li><code>app2Root: Software Cluster</code>, <code>app2Sub1: Software Cluster</code>, <code>app2Sub2: Software Cluster</code>: Die dreistufige Hierarchie aus Root- und Sub-Clustern samt gestrichelter Abhängigkeitspfeile entfällt und wird durch einen einzelnen Cluster <code>app2: Software Cluster</code> (Kategorie <code>APPLICATION_LAYER</code>) ersetzt, der direkt auf <code>shared: DiagnosticContributionSet</code> referenziert.\n</li><li>Notiz unten rechts: Textpassage „Only a single root Software Cluster specifies an diagnostic address.“ geändert zu „Only the DiagnosticContributionSet specifies an diagnostic address.“.\n</li></ul>"}]};
